bank.source(11,27,'rajshahi','O কেন্দ্রের বৃত্তে AB জ্যা; OC⊥AB এবং C জ্যার উপর। D বৃহৎ AB চাপে অবস্থিত। i. C, AB-এর মধ্যবিন্দু; ii. ∠OAC=∠OBC; iii. ∠OAC ও ∠OBC পরস্পর পূরক। কোনটি সাধারণভাবে সঠিক?',['i ও ii','i ও iii','ii ও iii','i, ii ও iii'],'A','I_II','কেন্দ্র থেকে জ্যার উপর লম্ব জ্যাকে সমদ্বিখণ্ডিত করে; OA=OB বলে ভূমিসংলগ্ন কোণদ্বয় সমান। তাদের যোগ সাধারণভাবে ৯০° নয়।',('chord',dict(r=5,d=3,midpoint='C',endB='B',top='D')),True)
